with account_totals as (select account_id, round(stddev(amount), 2) as stddev_amount, round(avg(amount), 2) as avg_amount from transactions where account_id in (16, 18, 30, 40) group by account_id) select accounts.id, accounts.account_type, accounts.customer_id, account_totals.stddev_amount, account_totals.avg_amount from accounts left outer join account_totals on accounts.id = account_totals.account_id where account_totals.stddev_amount >= 54 order by stddev_amount desc, accounts.id desc
